INSERT INTO `v1_600185d846ed1861f8f092fe6ab71c2be90c462036f617a5ab2e30723a3bb1f9` VALUES (1, "他のレンタルパーティを使用しているため、呼び出せません。", 1);
INSERT INTO `v1_600185d846ed1861f8f092fe6ab71c2be90c462036f617a5ab2e30723a3bb1f9` VALUES (2, "このレンタルパーティは本戦参加済のため、他の挑戦権で使用できません。", 2);
INSERT INTO `v1_600185d846ed1861f8f092fe6ab71c2be90c462036f617a5ab2e30723a3bb1f9` VALUES (3, "編成不可のキャラがいるため、このレンタルパーティは呼び出せません。", 3);
INSERT INTO `v1_600185d846ed1861f8f092fe6ab71c2be90c462036f617a5ab2e30723a3bb1f9` VALUES (4, "このバトルは編成可能な人数に制限があるため、レンタルパーティを使用できません。", 4);
INSERT INTO `v1_600185d846ed1861f8f092fe6ab71c2be90c462036f617a5ab2e30723a3bb1f9` VALUES (5, "全員が戦闘不能のため、このレンタルパーティは呼び出せません。", 5);
INSERT INTO `v1_600185d846ed1861f8f092fe6ab71c2be90c462036f617a5ab2e30723a3bb1f9` VALUES (6, "使用可能なレンタルパーティと編成人数が異なるため、呼び出せません。", 6);
